INSERT INTO products (id, slug, category_id, name, price, price_amount, price_label, image_url, image_alt, brand, status, sort_order, description, specifications) VALUES
(1, 'san-pham-1', 1, 'Tấm pin LONGi Hi MO X10 Scientist Hai Mặt Kính', '2560000', 2560000, NULL, '/uploads/products/tam_pin/1', 'Tấm pin LONGi Hi MO X10 Scientist Hai Mặt Kính - Chính hãng LONGi', 'LONGi', 'published', 10, 'Tấm pin LONGi Hi MO X10 Scientist Hai Mặt Kính là dòng pin quang điện cao cấp đến từ thương hiệu hàng đầu thế giới LONGi, ứng dụng công nghệ tế bào quang điện tiên tiến mang lại hiệu suất chuyển đổi quang năng tối đa cùng độ suy giảm thấp vượt trội theo thời gian.\n\nSản phẩm sở hữu cấu trúc khung hợp kim nhôm mạ anodized chắc chắn kết hợp mặt kính cường lực chịu tải trọng gió 2400Pa và tải trọng tuyết lên tới 5400Pa. Hộp nối dây đạt chuẩn chống nước bụi IP68 tích hợp diode bypass giúp triệt tiêu hiện tượng hot-spot và hạn chế tối đa tổn hao do bóng râm che khuất.\n\nĐược thiết kế tối ưu cho cả hệ thống điện mặt trời áp mái dân dụng, thương mại công nghiệp (C&I) và nhà máy điện mặt trời quy mô lớn, tấm pin đảm bảo mang lại hệ số hoàn vốn đầu tư (ROI) nhanh chóng cùng độ bền bỉ dài lâu suốt hơn 25 - 30 năm vận hành.', '[{\"label\":\"Công suất danh định (Pmax)\",\"value\":\"550 Wp\"},{\"label\":\"Công nghệ Cell\",\"value\":\"N-Type HPBC thế hệ mới (Không thanh busbar mặt trước)\"},{\"label\":\"Hiệu suất tấm pin\",\"value\":\"21.5\%\"},{\"label\":\"Điện áp hở mạch (Voc)\",\"value\":\"49.8 V\"},{\"label\":\"Dòng điện ngắn mạch (Isc)\",\"value\":\"14.05 A\"},{\"label\":\"Điện áp danh định (Vmp)\",\"value\":\"41.8 V\"},{\"label\":\"Dòng điện danh định (Imp)\",\"value\":\"13.16 A\"},{\"label\":\"Kích thước & Trọng lượng\",\"value\":\"2278 x 1134 x 35 mm | 28.5 kg\"},{\"label\":\"Cấu tạo mặt kính\",\"value\":\"Kính cường lực 3.2 mm phủ lớp chống phản xạ\"},{\"label\":\"Cấp độ bảo vệ\",\"value\":\"IP68 (3 bypass diodes), cáp 4mm²\"},{\"label\":\"Bảo hành vật lý\",\"value\":\"15 năm chính hãng\"},{\"label\":\"Bảo hành hiệu suất\",\"value\":\"30 năm hiệu suất (suy giảm năm đầu < 1\%)\"}]'),
(2, 'san-pham-2', 1, 'Tấm Pin Năng Lượng Mặt Trời LONGI Hi-MO X10', '2560000', 2560000, NULL, '/uploads/products/tam_pin/2', 'Tấm Pin Năng Lượng Mặt Trời LONGI Hi-MO X10 - Chính hãng LONGi', 'LONGi', 'published', 20, 'Tấm Pin Năng Lượng Mặt Trời LONGI Hi-MO X10 là dòng pin quang điện cao cấp đến từ thương hiệu hàng đầu thế giới LONGi, ứng dụng công nghệ tế bào quang điện tiên tiến mang lại hiệu suất chuyển đổi quang năng tối đa cùng độ suy giảm thấp vượt trội theo thời gian.\n\nSản phẩm sở hữu cấu trúc khung hợp kim nhôm mạ anodized chắc chắn kết hợp mặt kính cường lực chịu tải trọng gió 2400Pa và tải trọng tuyết lên tới 5400Pa. Hộp nối dây đạt chuẩn chống nước bụi IP68 tích hợp diode bypass giúp triệt tiêu hiện tượng hot-spot và hạn chế tối đa tổn hao do bóng râm che khuất.\n\nĐược thiết kế tối ưu cho cả hệ thống điện mặt trời áp mái dân dụng, thương mại công nghiệp (C&I) và nhà máy điện mặt trời quy mô lớn, tấm pin đảm bảo mang lại hệ số hoàn vốn đầu tư (ROI) nhanh chóng cùng độ bền bỉ dài lâu suốt hơn 25 - 30 năm vận hành.', '[{\"label\":\"Công suất danh định (Pmax)\",\"value\":\"550 Wp\"},{\"label\":\"Công nghệ Cell\",\"value\":\"N-Type HPBC thế hệ mới (Không thanh busbar mặt trước)\"},{\"label\":\"Hiệu suất tấm pin\",\"value\":\"21.5\%\"},{\"label\":\"Điện áp hở mạch (Voc)\",\"value\":\"49.8 V\"},{\"label\":\"Dòng điện ngắn mạch (Isc)\",\"value\":\"14.05 A\"},{\"label\":\"Điện áp danh định (Vmp)\",\"value\":\"41.8 V\"},{\"label\":\"Dòng điện danh định (Imp)\",\"value\":\"13.16 A\"},{\"label\":\"Kích thước & Trọng lượng\",\"value\":\"2278 x 1134 x 35 mm | 28.5 kg\"},{\"label\":\"Cấu tạo mặt kính\",\"value\":\"Kính cường lực 3.2 mm phủ lớp chống phản xạ\"},{\"label\":\"Cấp độ bảo vệ\",\"value\":\"IP68 (3 bypass diodes), cáp 4mm²\"},{\"label\":\"Bảo hành vật lý\",\"value\":\"15 năm chính hãng\"},{\"label\":\"Bảo hành hiệu suất\",\"value\":\"30 năm hiệu suất (suy giảm năm đầu < 1\%)\"}]'),
(3, 'san-pham-3', 1, 'Tấm Pin OSDA N ODA 590W MHD Hai Mặt Kính', '2360000', 2360000, NULL, '/uploads/products/tam_pin/3', 'Tấm Pin OSDA N ODA 590W MHD Hai Mặt Kính - Chính hãng OSDA', 'OSDA', 'published', 30, 'Tấm Pin OSDA N ODA 590W MHD Hai Mặt Kính là dòng pin quang điện cao cấp đến từ thương hiệu hàng đầu thế giới OSDA, ứng dụng công nghệ tế bào quang điện tiên tiến mang lại hiệu suất chuyển đổi quang năng tối đa cùng độ suy giảm thấp vượt trội theo thời gian.\n\nSản phẩm sở hữu cấu trúc khung hợp kim nhôm mạ anodized chắc chắn kết hợp mặt kính cường lực chịu tải trọng gió 2400Pa và tải trọng tuyết lên tới 5400Pa. Hộp nối dây đạt chuẩn chống nước bụi IP68 tích hợp diode bypass giúp triệt tiêu hiện tượng hot-spot và hạn chế tối đa tổn hao do bóng râm che khuất.\n\nĐược thiết kế tối ưu cho cả hệ thống điện mặt trời áp mái dân dụng, thương mại công nghiệp (C&I) và nhà máy điện mặt trời quy mô lớn, tấm pin đảm bảo mang lại hệ số hoàn vốn đầu tư (ROI) nhanh chóng cùng độ bền bỉ dài lâu suốt hơn 25 - 30 năm vận hành.', '[{\"label\":\"Công suất danh định (Pmax)\",\"value\":\"590 Wp\"},{\"label\":\"Công nghệ Cell\",\"value\":\"N-Type TOPCon Half-cut Cell đa thanh dẫn (SMBB)\"},{\"label\":\"Hiệu suất tấm pin\",\"value\":\"22.84\%\"},{\"label\":\"Điện áp hở mạch (Voc)\",\"value\":\"51.5 V\"},{\"label\":\"Dòng điện ngắn mạch (Isc)\",\"value\":\"14.45 A\"},{\"label\":\"Điện áp danh định (Vmp)\",\"value\":\"43.1 V\"},{\"label\":\"Dòng điện danh định (Imp)\",\"value\":\"13.69 A\"},{\"label\":\"Kích thước & Trọng lượng\",\"value\":\"2278 x 1134 x 30 mm | 31.8 kg\"},{\"label\":\"Cấu tạo mặt kính\",\"value\":\"Kính cường lực 3.2 mm phủ lớp chống phản xạ\"},{\"label\":\"Cấp độ bảo vệ\",\"value\":\"IP68 (3 bypass diodes), cáp 4mm²\"},{\"label\":\"Bảo hành vật lý\",\"value\":\"12 năm chính hãng\"},{\"label\":\"Bảo hành hiệu suất\",\"value\":\"30 năm hiệu suất (suy giảm hàng năm < 0.4\%)\"}]'),
