(13, 'san-pham-13', 1, 'Tấm pin năng lượng mặt trời LONGI Hi-Mo5 LR5-72HBD 540~560M', '2278100', 2278100, NULL, '/uploads/products/tam_pin/13', 'Tấm pin năng lượng mặt trời LONGI Hi-Mo5 LR5-72HBD 540~560M - Chính hãng LONGi', 'LONGi', 'published', 130, 'Tấm pin năng lượng mặt trời LONGI Hi-Mo5 LR5-72HBD 540~560M là dòng pin quang điện cao cấp đến từ thương hiệu hàng đầu thế giới LONGi, ứng dụng công nghệ tế bào quang điện tiên tiến mang lại hiệu suất chuyển đổi quang năng tối đa cùng độ suy giảm thấp vượt trội theo thời gian.\n\nSản phẩm sở hữu cấu trúc khung hợp kim nhôm mạ anodized chắc chắn kết hợp mặt kính cường lực chịu tải trọng gió 2400Pa và tải trọng tuyết lên tới 5400Pa. Hộp nối dây đạt chuẩn chống nước bụi IP68 tích hợp diode bypass giúp triệt tiêu hiện tượng hot-spot và hạn chế tối đa tổn hao do bóng râm che khuất.\n\nĐược thiết kế tối ưu cho cả hệ thống điện mặt trời áp mái dân dụng, thương mại công nghiệp (C&I) và nhà máy điện mặt trời quy mô lớn, tấm pin đảm bảo mang lại hệ số hoàn vốn đầu tư (ROI) nhanh chóng cùng độ bền bỉ dài lâu suốt hơn 25 - 30 năm vận hành.', '[{\"label\":\"Công suất danh định (Pmax)\",\"value\":\"550 Wp\"},{\"label\":\"Công nghệ Cell\",\"value\":\"Đơn tinh thể Mono PERC\"},{\"label\":\"Hiệu suất tấm pin\",\"value\":\"21.5\%\"},{\"label\":\"Điện áp hở mạch (Voc)\",\"value\":\"49.8 V\"},{\"label\":\"Dòng điện ngắn mạch (Isc)\",\"value\":\"13.98 A\"},{\"label\":\"Điện áp danh định (Vmp)\",\"value\":\"41.9 V\"},{\"label\":\"Dòng điện danh định (Imp)\",\"value\":\"13.13 A\"},{\"label\":\"Kích thước & Trọng lượng\",\"value\":\"2278 x 1134 x 35 mm | 28.6 kg\"},{\"label\":\"Cấu tạo mặt kính\",\"value\":\"Kính cường lực 3.2 mm phủ lớp chống phản xạ\"},{\"label\":\"Cấp độ bảo vệ\",\"value\":\"IP68 (3 bypass diodes), cáp 4mm²\"},{\"label\":\"Bảo hành vật lý\",\"value\":\"12 năm vật lý\"},{\"label\":\"Bảo hành hiệu suất\",\"value\":\"25 năm hiệu suất trên 84.8\%\"}]'),
