(18, 'san-pham-18', 1, 'Tấm pin năng lượng mặt trời Jinko Tiger Neo N-Type 78HL4-BDV 605-625W', 'Lien he', NULL, 'Liên hệ', '/uploads/products/tam_pin/18', 'Tấm pin năng lượng mặt trời Jinko Tiger Neo N-Type 78HL4-BDV 605-625W - Chính hãng Jinko', 'Jinko', 'published', 180, 'Tấm pin năng lượng mặt trời Jinko Tiger Neo N-Type 78HL4-BDV 605-625W là dòng pin quang điện cao cấp đến từ thương hiệu hàng đầu thế giới Jinko, ứng dụng công nghệ tế bào quang điện tiên tiến mang lại hiệu suất chuyển đổi quang năng tối đa cùng độ suy giảm thấp vượt trội theo thời gian.\n\nSản phẩm sở hữu cấu trúc khung hợp kim nhôm mạ anodized chắc chắn kết hợp mặt kính cường lực chịu tải trọng gió 2400Pa và tải trọng tuyết lên tới 5400Pa. Hộp nối dây đạt chuẩn chống nước bụi IP68 tích hợp diode bypass giúp triệt tiêu hiện tượng hot-spot và hạn chế tối đa tổn hao do bóng râm che khuất.\n\nĐược thiết kế tối ưu cho cả hệ thống điện mặt trời áp mái dân dụng, thương mại công nghiệp (C&I) và nhà máy điện mặt trời quy mô lớn, tấm pin đảm bảo mang lại hệ số hoàn vốn đầu tư (ROI) nhanh chóng cùng độ bền bỉ dài lâu suốt hơn 25 - 30 năm vận hành.', '[{\"label\":\"Công suất danh định (Pmax)\",\"value\":\"620 Wp\"},{\"label\":\"Công nghệ Cell\",\"value\":\"N-Type TOPCon Half-cut Cell đa thanh dẫn (SMBB)\"},{\"label\":\"Hiệu suất tấm pin\",\"value\":\"23.0\%\"},{\"label\":\"Điện áp hở mạch (Voc)\",\"value\":\"55.4 V\"},{\"label\":\"Dòng điện ngắn mạch (Isc)\",\"value\":\"14.15 A\"},{\"label\":\"Điện áp danh định (Vmp)\",\"value\":\"46.2 V\"},{\"label\":\"Dòng điện danh định (Imp)\",\"value\":\"13.42 A\"},{\"label\":\"Kích thước & Trọng lượng\",\"value\":\"2382 x 1134 x 30 mm | 33.5 kg\"},{\"label\":\"Cấu tạo mặt kính\",\"value\":\"Kính cường lực 2 mặt (2.0mm + 2.0mm)\"},{\"label\":\"Cấp độ bảo vệ\",\"value\":\"IP68 (3 bypass diodes), cáp 4mm²\"},{\"label\":\"Bảo hành vật lý\",\"value\":\"12 năm chính hãng\"},{\"label\":\"Bảo hành hiệu suất\",\"value\":\"30 năm hiệu suất (suy giảm hàng năm < 0.4\%)\"}]'),
