(23, 'san-pham-23', 1, 'Tấm pin năng lượng mặt trời Jinko Tiger Pro 72HC-BDVP 530-550W', '2052000', 2052000, NULL, '/uploads/products/tam_pin/23', 'Tấm pin năng lượng mặt trời Jinko Tiger Pro 72HC-BDVP 530-550W - Chính hãng Jinko', 'Jinko', 'published', 230, 'Tấm pin năng lượng mặt trời Jinko Tiger Pro 72HC-BDVP 530-550W là dòng pin quang điện cao cấp đến từ thương hiệu hàng đầu thế giới Jinko, ứng dụng công nghệ tế bào quang điện tiên tiến mang lại hiệu suất chuyển đổi quang năng tối đa cùng độ suy giảm thấp vượt trội theo thời gian.\n\nSản phẩm sở hữu cấu trúc khung hợp kim nhôm mạ anodized chắc chắn kết hợp mặt kính cường lực chịu tải trọng gió 2400Pa và tải trọng tuyết lên tới 5400Pa. Hộp nối dây đạt chuẩn chống nước bụi IP68 tích hợp diode bypass giúp triệt tiêu hiện tượng hot-spot và hạn chế tối đa tổn hao do bóng râm che khuất.\n\nĐược thiết kế tối ưu cho cả hệ thống điện mặt trời áp mái dân dụng, thương mại công nghiệp (C&I) và nhà máy điện mặt trời quy mô lớn, tấm pin đảm bảo mang lại hệ số hoàn vốn đầu tư (ROI) nhanh chóng cùng độ bền bỉ dài lâu suốt hơn 25 - 30 năm vận hành.', '[{\"label\":\"Công suất danh định (Pmax)\",\"value\":\"550 Wp\"},{\"label\":\"Công nghệ Cell\",\"value\":\"Đơn tinh thể Mono PERC\"},{\"label\":\"Hiệu suất tấm pin\",\"value\":\"21.5\%\"},{\"label\":\"Điện áp hở mạch (Voc)\",\"value\":\"49.8 V\"},{\"label\":\"Dòng điện ngắn mạch (Isc)\",\"value\":\"13.98 A\"},{\"label\":\"Điện áp danh định (Vmp)\",\"value\":\"41.9 V\"},{\"label\":\"Dòng điện danh định (Imp)\",\"value\":\"13.13 A\"},{\"label\":\"Kích thước & Trọng lượng\",\"value\":\"2278 x 1134 x 35 mm | 28.6 kg\"},{\"label\":\"Cấu tạo mặt kính\",\"value\":\"Kính cường lực 2 mặt (2.0mm + 2.0mm)\"},{\"label\":\"Cấp độ bảo vệ\",\"value\":\"IP68 (3 bypass diodes), cáp 4mm²\"},{\"label\":\"Bảo hành vật lý\",\"value\":\"12 năm vật lý\"},{\"label\":\"Bảo hành hiệu suất\",\"value\":\"30 năm hiệu suất tuyến tính (trên 87.4\%)\"}]'),
(24, 'san-pham-24', 1, 'Tấm pin năng lượng mặt trời LONGI Hi-MO 9', 'Lien he', NULL, 'Liên hệ', '/uploads/products/tam_pin/24', 'Tấm pin năng lượng mặt trời LONGI Hi-MO 9 - Chính hãng LONGi', 'LONGi', 'published', 240, 'Tấm pin năng lượng mặt trời LONGI Hi-MO 9 là dòng pin quang điện cao cấp đến từ thương hiệu hàng đầu thế giới LONGi, ứng dụng công nghệ tế bào quang điện tiên tiến mang lại hiệu suất chuyển đổi quang năng tối đa cùng độ suy giảm thấp vượt trội theo thời gian.\n\nSản phẩm sở hữu cấu trúc khung hợp kim nhôm mạ anodized chắc chắn kết hợp mặt kính cường lực chịu tải trọng gió 2400Pa và tải trọng tuyết lên tới 5400Pa. Hộp nối dây đạt chuẩn chống nước bụi IP68 tích hợp diode bypass giúp triệt tiêu hiện tượng hot-spot và hạn chế tối đa tổn hao do bóng râm che khuất.\n\nĐược thiết kế tối ưu cho cả hệ thống điện mặt trời áp mái dân dụng, thương mại công nghiệp (C&I) và nhà máy điện mặt trời quy mô lớn, tấm pin đảm bảo mang lại hệ số hoàn vốn đầu tư (ROI) nhanh chóng cùng độ bền bỉ dài lâu suốt hơn 25 - 30 năm vận hành.', '[{\"label\":\"Công suất danh định (Pmax)\",\"value\":\"620 Wp\"},{\"label\":\"Công nghệ Cell\",\"value\":\"N-Type HPBC thế hệ mới (Không thanh busbar mặt trước)\"},{\"label\":\"Hiệu suất tấm pin\",\"value\":\"23.0\%\"},{\"label\":\"Điện áp hở mạch (Voc)\",\"value\":\"55.4 V\"},{\"label\":\"Dòng điện ngắn mạch (Isc)\",\"value\":\"14.15 A\"},{\"label\":\"Điện áp danh định (Vmp)\",\"value\":\"46.2 V\"},{\"label\":\"Dòng điện danh định (Imp)\",\"value\":\"13.42 A\"},{\"label\":\"Kích thước & Trọng lượng\",\"value\":\"2382 x 1134 x 30 mm | 33.5 kg\"},{\"label\":\"Cấu tạo mặt kính\",\"value\":\"Kính cường lực 3.2 mm phủ lớp chống phản xạ\"},{\"label\":\"Cấp độ bảo vệ\",\"value\":\"IP68 (3 bypass diodes), cáp 4mm²\"},{\"label\":\"Bảo hành vật lý\",\"value\":\"15 năm chính hãng\"},{\"label\":\"Bảo hành hiệu suất\",\"value\":\"30 năm hiệu suất (suy giảm năm đầu < 1\%)\"}]'),
(25, 'san-pham-25', 2, 'Inverter hybrid Solis S6-EH1P(3-10)K-L-PLUS', '25990000', 25990000, NULL, '/uploads/products/inverter/1', 'Inverter hybrid Solis S6-EH1P(3-10)K-L-PLUS - Chính hãng Solis', 'Solis', 'published', 250, 'Inverter hybrid Solis S6-EH1P(3-10)K-L-PLUS là thiết bị biến tần lưu trữ thông minh (Hybrid Inverter) cao cấp đến từ thương hiệu Solis, giải pháp toàn diện cho nguồn điện ổn định 24/7. Thiết bị cho phép điều phối linh hoạt giữa nguồn năng lượng mặt trời, pin lưu trữ và điện lưới quốc gia.\n\nSản phẩm sở hữu chức năng chuyển đổi nguồn dự phòng UPS siêu tốc (< 10ms), đảm bảo các tải quan trọng không bị gián đoạn khi xảy ra sự cố mất điện lưới. Tích hợp màn hình cảm ứng LCD hoặc đèn hiển thị LED trực quan, cùng cổng kết nối thông minh Wi-Fi/4G giúp theo dõi sản lượng và quản lý năng lượng theo thời gian thực trên điện thoại di động.\n\nTương thích hoàn hảo với các dòng pin lưu trữ Lithium điện áp thấp (48V/51.2V) hoặc áp cao (High Voltage), hỗ trợ cài đặt xả theo giờ cao điểm (Peak-shaving) và kiểm soát bám tải không phát ngược lưới Zero-Export an toàn, thông minh.', '[{\"label\":\"Loại biến tần\",\"value\":\"Biến tần lưu trữ Hybrid 1 Pha\"},{\"label\":\"Công suất AC định mức\",\"value\":\"10 kW\"},{\"label\":\"Điện áp đầu ra lưới\",\"value\":\"1 Pha (220V / 230V, L+N+PE)\"},{\"label\":\"Điện áp đầu vào PV cực đại\",\"value\":\"550V - 600V DC\"},{\"label\":\"Dải điện áp MPPT\",\"value\":\"90V – 520V DC\"},{\"label\":\"Số lượng MPPT\",\"value\":\"2 MPPT\"},{\"label\":\"Tương thích pin lưu trữ\",\"value\":\"Pin Lithium 48V / 51.2V (LiFePO4)\"},{\"label\":\"Thời gian chuyển mạch UPS\",\"value\":\"< 10 ms (Cấp nguồn liên tục không ngắt quãng)\"},{\"label\":\"Hiệu suất tối đa\",\"value\":\"97.6\% - 98.2\%\"},{\"label\":\"Cấp độ bảo vệ môi trường\",\"value\":\"IP65 / IP66 (Lắp đặt trong nhà hoặc ngoài trời)\"},{\"label\":\"Cổng giao tiếp giám sát\",\"value\":\"RS485, CAN, Wi-Fi / LAN, DRM\"},{\"label\":\"Bảo hành tiêu chuẩn\",\"value\":\"5 năm chính hãng (Mở rộng tùy chọn đến 10 năm)\"}]'),
