(35, 'san-pham-35', 2, 'Inverter hòa lưới Solis S5-GR3P20K 20kW | 3 pha | 2 MPPT', '31083000', 31083000, NULL, '/uploads/products/inverter/11', 'Inverter hòa lưới Solis S5-GR3P20K 20kW | 3 pha | 2 MPPT - Chính hãng Solis', 'Solis', 'published', 350, 'Inverter hòa lưới Solis S5-GR3P20K 20kW | 3 pha | 2 MPPT là dòng biến tần hòa lưới (On-grid Inverter) hiệu suất cao của thương hiệu Solis, được tối ưu hóa cho hiệu năng phát điện bền bỉ và ổn định tối đa dưới điều kiện khí hậu nhiệt đới.\n\nThiết bị tích hợp công nghệ dò điểm công suất cực đại MPPT tiên tiến với dải điện áp làm việc rộng, giúp khởi động sớm và tắt muộn để tận dụng tối đa năng lượng mặt trời mỗi ngày. Hệ thống tản nhiệt thông minh không dùng quạt ngoài (đối với model dân dụng) hoặc quạt tản nhiệt thông minh IP68 giúp máy hoạt động êm ái, kéo dài tuổi thọ linh kiện.\n\nHỗ trợ kết nối giám sát từ xa thông minh qua ứng dụng di động Cloud, tích hợp sẵn các cấp độ bảo vệ an toàn: chống sét lan truyền Type II (DC/AC), chống đảo pha, bảo vệ quá áp, quá dòng và chức năng ngắt hồ quang AFCI an toàn phòng chống cháy nổ.', '[{\"label\":\"Loại biến tần\",\"value\":\"Biến tần hòa lưới 3 Pha\"},{\"label\":\"Công suất phát định mức\",\"value\":\"20 kW\"},{\"label\":\"Điện áp ra AC\",\"value\":\"3 Pha (380V / 400V, 3L+N+PE)\"},{\"label\":\"Điện áp đầu vào PV cực đại\",\"value\":\"1000V - 1100V DC\"},{\"label\":\"Dải điện áp hoạt động MPPT\",\"value\":\"160V – 960V DC\"},{\"label\":\"Số lượng bộ theo dõi MPPT\",\"value\":\"2 MPPT\"},{\"label\":\"Hiệu suất chuyển đổi cực đại\",\"value\":\"98.6\% - 98.8\%\"},{\"label\":\"Tần số điện lưới danh định\",\"value\":\"50 Hz / 60 Hz (Tự động thích ứng)\"},{\"label\":\"Cấp bảo vệ chống nước, bụi\",\"value\":\"IP65 / IP66 tiêu chuẩn quốc tế\"},{\"label\":\"Tính năng bảo vệ\",\"value\":\"Chống phát ngược (Zero-export), chống đảo pha, AFCI\"},{\"label\":\"Giao thức truyền thông\",\"value\":\"Wi-Fi, RS485, GPRS / 4G (Tùy chọn)\"},{\"label\":\"Thời gian bảo hành\",\"value\":\"5 năm tiêu chuẩn từ nhà sản xuất\"}]'),
(36, 'san-pham-36', 2, 'Inverter hòa lưới Hypontech HPS-10000 | 1 pha | 3 MPPT', '19278000', 19278000, NULL, '/uploads/products/inverter/12', 'Inverter hòa lưới Hypontech HPS-10000 | 1 pha | 3 MPPT - Chính hãng Hypontech', 'Hypontech', 'published', 360, 'Inverter hòa lưới Hypontech HPS-10000 | 1 pha | 3 MPPT là dòng biến tần hòa lưới (On-grid Inverter) hiệu suất cao của thương hiệu Hypontech, được tối ưu hóa cho hiệu năng phát điện bền bỉ và ổn định tối đa dưới điều kiện khí hậu nhiệt đới.\n\nThiết bị tích hợp công nghệ dò điểm công suất cực đại MPPT tiên tiến với dải điện áp làm việc rộng, giúp khởi động sớm và tắt muộn để tận dụng tối đa năng lượng mặt trời mỗi ngày. Hệ thống tản nhiệt thông minh không dùng quạt ngoài (đối với model dân dụng) hoặc quạt tản nhiệt thông minh IP68 giúp máy hoạt động êm ái, kéo dài tuổi thọ linh kiện.\n\nHỗ trợ kết nối giám sát từ xa thông minh qua ứng dụng di động Cloud, tích hợp sẵn các cấp độ bảo vệ an toàn: chống sét lan truyền Type II (DC/AC), chống đảo pha, bảo vệ quá áp, quá dòng và chức năng ngắt hồ quang AFCI an toàn phòng chống cháy nổ.', '[{\"label\":\"Loại biến tần\",\"value\":\"Biến tần hòa lưới 1 Pha\"},{\"label\":\"Công suất phát định mức\",\"value\":\"10 kW\"},{\"label\":\"Điện áp ra AC\",\"value\":\"1 Pha (220V / 230V, L+N+PE)\"},{\"label\":\"Điện áp đầu vào PV cực đại\",\"value\":\"550V - 600V DC\"},{\"label\":\"Dải điện áp hoạt động MPPT\",\"value\":\"90V – 520V DC\"},{\"label\":\"Số lượng bộ theo dõi MPPT\",\"value\":\"3 MPPT\"},{\"label\":\"Hiệu suất chuyển đổi cực đại\",\"value\":\"97.6\% - 98.2\%\"},{\"label\":\"Tần số điện lưới danh định\",\"value\":\"50 Hz / 60 Hz (Tự động thích ứng)\"},{\"label\":\"Cấp bảo vệ chống nước, bụi\",\"value\":\"IP65 / IP66 tiêu chuẩn quốc tế\"},{\"label\":\"Tính năng bảo vệ\",\"value\":\"Chống phát ngược (Zero-export), chống đảo pha, AFCI\"},{\"label\":\"Giao thức truyền thông\",\"value\":\"Wi-Fi, RS485, GPRS / 4G (Tùy chọn)\"},{\"label\":\"Thời gian bảo hành\",\"value\":\"5 năm tiêu chuẩn từ nhà sản xuất\"}]'),
