(50, 'san-pham-50', 2, 'Inverter Hybrid SENERGY 10kw SE 10KHB-210-T/EU', '46200000', 46200000, NULL, '/uploads/products/inverter/26', 'Inverter Hybrid SENERGY 10kw SE 10KHB-210-T/EU - Chính hãng Senergy', 'Senergy', 'published', 500, 'Inverter Hybrid SENERGY 10kw SE 10KHB-210-T/EU là thiết bị biến tần lưu trữ thông minh (Hybrid Inverter) cao cấp đến từ thương hiệu Senergy, giải pháp toàn diện cho nguồn điện ổn định 24/7. Thiết bị cho phép điều phối linh hoạt giữa nguồn năng lượng mặt trời, pin lưu trữ và điện lưới quốc gia.\n\nSản phẩm sở hữu chức năng chuyển đổi nguồn dự phòng UPS siêu tốc (< 10ms), đảm bảo các tải quan trọng không bị gián đoạn khi xảy ra sự cố mất điện lưới. Tích hợp màn hình cảm ứng LCD hoặc đèn hiển thị LED trực quan, cùng cổng kết nối thông minh Wi-Fi/4G giúp theo dõi sản lượng và quản lý năng lượng theo thời gian thực trên điện thoại di động.\n\nTương thích hoàn hảo với các dòng pin lưu trữ Lithium điện áp thấp (48V/51.2V) hoặc áp cao (High Voltage), hỗ trợ cài đặt xả theo giờ cao điểm (Peak-shaving) và kiểm soát bám tải không phát ngược lưới Zero-Export an toàn, thông minh.', '[{\"label\":\"Loại biến tần\",\"value\":\"Biến tần lưu trữ Hybrid 3 Pha\"},{\"label\":\"Công suất AC định mức\",\"value\":\"10 kW\"},{\"label\":\"Điện áp đầu ra lưới\",\"value\":\"3 Pha (380V / 400V, 3L+N+PE)\"},{\"label\":\"Điện áp đầu vào PV cực đại\",\"value\":\"1000V - 1100V DC\"},{\"label\":\"Dải điện áp MPPT\",\"value\":\"160V – 960V DC\"},{\"label\":\"Số lượng MPPT\",\"value\":\"2 MPPT\"},{\"label\":\"Tương thích pin lưu trữ\",\"value\":\"Pin Lithium 48V / 51.2V (LiFePO4)\"},{\"label\":\"Thời gian chuyển mạch UPS\",\"value\":\"< 10 ms (Cấp nguồn liên tục không ngắt quãng)\"},{\"label\":\"Hiệu suất tối đa\",\"value\":\"98.6\% - 98.8\%\"},{\"label\":\"Cấp độ bảo vệ môi trường\",\"value\":\"IP65 / IP66 (Lắp đặt trong nhà hoặc ngoài trời)\"},{\"label\":\"Cổng giao tiếp giám sát\",\"value\":\"RS485, CAN, Wi-Fi / LAN, DRM\"},{\"label\":\"Bảo hành tiêu chuẩn\",\"value\":\"5 năm chính hãng (Mở rộng tùy chọn đến 10 năm)\"}]'),
(51, 'san-pham-51', 2, 'Inverter Hybrid SENERGY 8kw SE 8KHB-210-T/EU', '40110000', 40110000, NULL, '/uploads/products/inverter/27', 'Inverter Hybrid SENERGY 8kw SE 8KHB-210-T/EU - Chính hãng Senergy', 'Senergy', 'published', 510, 'Inverter Hybrid SENERGY 8kw SE 8KHB-210-T/EU là thiết bị biến tần lưu trữ thông minh (Hybrid Inverter) cao cấp đến từ thương hiệu Senergy, giải pháp toàn diện cho nguồn điện ổn định 24/7. Thiết bị cho phép điều phối linh hoạt giữa nguồn năng lượng mặt trời, pin lưu trữ và điện lưới quốc gia.\n\nSản phẩm sở hữu chức năng chuyển đổi nguồn dự phòng UPS siêu tốc (< 10ms), đảm bảo các tải quan trọng không bị gián đoạn khi xảy ra sự cố mất điện lưới. Tích hợp màn hình cảm ứng LCD hoặc đèn hiển thị LED trực quan, cùng cổng kết nối thông minh Wi-Fi/4G giúp theo dõi sản lượng và quản lý năng lượng theo thời gian thực trên điện thoại di động.\n\nTương thích hoàn hảo với các dòng pin lưu trữ Lithium điện áp thấp (48V/51.2V) hoặc áp cao (High Voltage), hỗ trợ cài đặt xả theo giờ cao điểm (Peak-shaving) và kiểm soát bám tải không phát ngược lưới Zero-Export an toàn, thông minh.', '[{\"label\":\"Loại biến tần\",\"value\":\"Biến tần lưu trữ Hybrid 3 Pha\"},{\"label\":\"Công suất AC định mức\",\"value\":\"8 kW\"},{\"label\":\"Điện áp đầu ra lưới\",\"value\":\"3 Pha (380V / 400V, 3L+N+PE)\"},{\"label\":\"Điện áp đầu vào PV cực đại\",\"value\":\"1000V - 1100V DC\"},{\"label\":\"Dải điện áp MPPT\",\"value\":\"160V – 960V DC\"},{\"label\":\"Số lượng MPPT\",\"value\":\"2 MPPT\"},{\"label\":\"Tương thích pin lưu trữ\",\"value\":\"Pin Lithium 48V / 51.2V (LiFePO4)\"},{\"label\":\"Thời gian chuyển mạch UPS\",\"value\":\"< 10 ms (Cấp nguồn liên tục không ngắt quãng)\"},{\"label\":\"Hiệu suất tối đa\",\"value\":\"98.6\% - 98.8\%\"},{\"label\":\"Cấp độ bảo vệ môi trường\",\"value\":\"IP65 / IP66 (Lắp đặt trong nhà hoặc ngoài trời)\"},{\"label\":\"Cổng giao tiếp giám sát\",\"value\":\"RS485, CAN, Wi-Fi / LAN, DRM\"},{\"label\":\"Bảo hành tiêu chuẩn\",\"value\":\"5 năm chính hãng (Mở rộng tùy chọn đến 10 năm)\"}]'),
