(53, 'san-pham-53', 2, 'Inverter Hybrid SENERGY 5kw SE 5KHB-120', '24832500', 24832500, NULL, '/uploads/products/inverter/29', 'Inverter Hybrid SENERGY 5kw SE 5KHB-120 - Chính hãng Senergy', 'Senergy', 'published', 530, 'Inverter Hybrid SENERGY 5kw SE 5KHB-120 là thiết bị biến tần lưu trữ thông minh (Hybrid Inverter) cao cấp đến từ thương hiệu Senergy, giải pháp toàn diện cho nguồn điện ổn định 24/7. Thiết bị cho phép điều phối linh hoạt giữa nguồn năng lượng mặt trời, pin lưu trữ và điện lưới quốc gia.\n\nSản phẩm sở hữu chức năng chuyển đổi nguồn dự phòng UPS siêu tốc (< 10ms), đảm bảo các tải quan trọng không bị gián đoạn khi xảy ra sự cố mất điện lưới. Tích hợp màn hình cảm ứng LCD hoặc đèn hiển thị LED trực quan, cùng cổng kết nối thông minh Wi-Fi/4G giúp theo dõi sản lượng và quản lý năng lượng theo thời gian thực trên điện thoại di động.\n\nTương thích hoàn hảo với các dòng pin lưu trữ Lithium điện áp thấp (48V/51.2V) hoặc áp cao (High Voltage), hỗ trợ cài đặt xả theo giờ cao điểm (Peak-shaving) và kiểm soát bám tải không phát ngược lưới Zero-Export an toàn, thông minh.', '[{\"label\":\"Loại biến tần\",\"value\":\"Biến tần lưu trữ Hybrid 1 Pha\"},{\"label\":\"Công suất AC định mức\",\"value\":\"5 kW\"},{\"label\":\"Điện áp đầu ra lưới\",\"value\":\"1 Pha (220V / 230V, L+N+PE)\"},{\"label\":\"Điện áp đầu vào PV cực đại\",\"value\":\"550V - 600V DC\"},{\"label\":\"Dải điện áp MPPT\",\"value\":\"90V – 520V DC\"},{\"label\":\"Số lượng MPPT\",\"value\":\"2 MPPT\"},{\"label\":\"Tương thích pin lưu trữ\",\"value\":\"Pin Lithium 48V / 51.2V (LiFePO4)\"},{\"label\":\"Thời gian chuyển mạch UPS\",\"value\":\"< 10 ms (Cấp nguồn liên tục không ngắt quãng)\"},{\"label\":\"Hiệu suất tối đa\",\"value\":\"97.6\% - 98.2\%\"},{\"label\":\"Cấp độ bảo vệ môi trường\",\"value\":\"IP65 / IP66 (Lắp đặt trong nhà hoặc ngoài trời)\"},{\"label\":\"Cổng giao tiếp giám sát\",\"value\":\"RS485, CAN, Wi-Fi / LAN, DRM\"},{\"label\":\"Bảo hành tiêu chuẩn\",\"value\":\"5 năm chính hãng (Mở rộng tùy chọn đến 10 năm)\"}]'),
(54, 'san-pham-54', 2, 'Inverter hòa lưới Growatt 125KW MAX125-KTL3-LV', '119700000', 119700000, NULL, '/uploads/products/inverter/30', 'Inverter hòa lưới Growatt 125KW MAX125-KTL3-LV - Chính hãng Growatt', 'Growatt', 'published', 540, 'Inverter hòa lưới Growatt 125KW MAX125-KTL3-LV là dòng biến tần hòa lưới (On-grid Inverter) hiệu suất cao của thương hiệu Growatt, được tối ưu hóa cho hiệu năng phát điện bền bỉ và ổn định tối đa dưới điều kiện khí hậu nhiệt đới.\n\nThiết bị tích hợp công nghệ dò điểm công suất cực đại MPPT tiên tiến với dải điện áp làm việc rộng, giúp khởi động sớm và tắt muộn để tận dụng tối đa năng lượng mặt trời mỗi ngày. Hệ thống tản nhiệt thông minh không dùng quạt ngoài (đối với model dân dụng) hoặc quạt tản nhiệt thông minh IP68 giúp máy hoạt động êm ái, kéo dài tuổi thọ linh kiện.\n\nHỗ trợ kết nối giám sát từ xa thông minh qua ứng dụng di động Cloud, tích hợp sẵn các cấp độ bảo vệ an toàn: chống sét lan truyền Type II (DC/AC), chống đảo pha, bảo vệ quá áp, quá dòng và chức năng ngắt hồ quang AFCI an toàn phòng chống cháy nổ.', '[{\"label\":\"Loại biến tần\",\"value\":\"Biến tần hòa lưới 3 Pha\"},{\"label\":\"Công suất phát định mức\",\"value\":\"125 kW\"},{\"label\":\"Điện áp ra AC\",\"value\":\"3 Pha (380V / 400V, 3L+N+PE)\"},{\"label\":\"Điện áp đầu vào PV cực đại\",\"value\":\"1000V - 1100V DC\"},{\"label\":\"Dải điện áp hoạt động MPPT\",\"value\":\"160V – 960V DC\"},{\"label\":\"Số lượng bộ theo dõi MPPT\",\"value\":\"6 - 8 MPPT\"},{\"label\":\"Hiệu suất chuyển đổi cực đại\",\"value\":\"98.6\% - 98.8\%\"},{\"label\":\"Tần số điện lưới danh định\",\"value\":\"50 Hz / 60 Hz (Tự động thích ứng)\"},{\"label\":\"Cấp bảo vệ chống nước, bụi\",\"value\":\"IP65 / IP66 tiêu chuẩn quốc tế\"},{\"label\":\"Tính năng bảo vệ\",\"value\":\"Chống phát ngược (Zero-export), chống đảo pha, AFCI\"},{\"label\":\"Giao thức truyền thông\",\"value\":\"Wi-Fi, RS485, GPRS / 4G (Tùy chọn)\"},{\"label\":\"Thời gian bảo hành\",\"value\":\"5 năm tiêu chuẩn từ nhà sản xuất\"}]'),
