(63, 'san-pham-63', 2, 'Inverter hòa lưới Solis S5-GR3P15K | 3 pha | 15kw', '27464000', 27464000, NULL, '/uploads/products/inverter/39', 'Inverter hòa lưới Solis S5-GR3P15K | 3 pha | 15kw - Chính hãng Solis', 'Solis', 'published', 630, 'Inverter hòa lưới Solis S5-GR3P15K | 3 pha | 15kw là dòng biến tần hòa lưới (On-grid Inverter) hiệu suất cao của thương hiệu Solis, được tối ưu hóa cho hiệu năng phát điện bền bỉ và ổn định tối đa dưới điều kiện khí hậu nhiệt đới.\n\nThiết bị tích hợp công nghệ dò điểm công suất cực đại MPPT tiên tiến với dải điện áp làm việc rộng, giúp khởi động sớm và tắt muộn để tận dụng tối đa năng lượng mặt trời mỗi ngày. Hệ thống tản nhiệt thông minh không dùng quạt ngoài (đối với model dân dụng) hoặc quạt tản nhiệt thông minh IP68 giúp máy hoạt động êm ái, kéo dài tuổi thọ linh kiện.\n\nHỗ trợ kết nối giám sát từ xa thông minh qua ứng dụng di động Cloud, tích hợp sẵn các cấp độ bảo vệ an toàn: chống sét lan truyền Type II (DC/AC), chống đảo pha, bảo vệ quá áp, quá dòng và chức năng ngắt hồ quang AFCI an toàn phòng chống cháy nổ.', '[{\"label\":\"Loại biến tần\",\"value\":\"Biến tần hòa lưới 3 Pha\"},{\"label\":\"Công suất phát định mức\",\"value\":\"15 kW\"},{\"label\":\"Điện áp ra AC\",\"value\":\"3 Pha (380V / 400V, 3L+N+PE)\"},{\"label\":\"Điện áp đầu vào PV cực đại\",\"value\":\"1000V - 1100V DC\"},{\"label\":\"Dải điện áp hoạt động MPPT\",\"value\":\"160V – 960V DC\"},{\"label\":\"Số lượng bộ theo dõi MPPT\",\"value\":\"2 MPPT\"},{\"label\":\"Hiệu suất chuyển đổi cực đại\",\"value\":\"98.6\% - 98.8\%\"},{\"label\":\"Tần số điện lưới danh định\",\"value\":\"50 Hz / 60 Hz (Tự động thích ứng)\"},{\"label\":\"Cấp bảo vệ chống nước, bụi\",\"value\":\"IP65 / IP66 tiêu chuẩn quốc tế\"},{\"label\":\"Tính năng bảo vệ\",\"value\":\"Chống phát ngược (Zero-export), chống đảo pha, AFCI\"},{\"label\":\"Giao thức truyền thông\",\"value\":\"Wi-Fi, RS485, GPRS / 4G (Tùy chọn)\"},{\"label\":\"Thời gian bảo hành\",\"value\":\"5 năm tiêu chuẩn từ nhà sản xuất\"}]'),
(64, 'san-pham-64', 2, 'Inverter Hybrid Solis S6 EH1P6K-L-PRO(SN)', '26399000', 26399000, NULL, '/uploads/products/inverter/40', 'Inverter Hybrid Solis S6 EH1P6K-L-PRO(SN) - Chính hãng Solis', 'Solis', 'published', 640, 'Inverter Hybrid Solis S6 EH1P6K-L-PRO(SN) là thiết bị biến tần lưu trữ thông minh (Hybrid Inverter) cao cấp đến từ thương hiệu Solis, giải pháp toàn diện cho nguồn điện ổn định 24/7. Thiết bị cho phép điều phối linh hoạt giữa nguồn năng lượng mặt trời, pin lưu trữ và điện lưới quốc gia.\n\nSản phẩm sở hữu chức năng chuyển đổi nguồn dự phòng UPS siêu tốc (< 10ms), đảm bảo các tải quan trọng không bị gián đoạn khi xảy ra sự cố mất điện lưới. Tích hợp màn hình cảm ứng LCD hoặc đèn hiển thị LED trực quan, cùng cổng kết nối thông minh Wi-Fi/4G giúp theo dõi sản lượng và quản lý năng lượng theo thời gian thực trên điện thoại di động.\n\nTương thích hoàn hảo với các dòng pin lưu trữ Lithium điện áp thấp (48V/51.2V) hoặc áp cao (High Voltage), hỗ trợ cài đặt xả theo giờ cao điểm (Peak-shaving) và kiểm soát bám tải không phát ngược lưới Zero-Export an toàn, thông minh.', '[{\"label\":\"Loại biến tần\",\"value\":\"Biến tần lưu trữ Hybrid 1 Pha\"},{\"label\":\"Công suất AC định mức\",\"value\":\"6 kW\"},{\"label\":\"Điện áp đầu ra lưới\",\"value\":\"1 Pha (220V / 230V, L+N+PE)\"},{\"label\":\"Điện áp đầu vào PV cực đại\",\"value\":\"550V - 600V DC\"},{\"label\":\"Dải điện áp MPPT\",\"value\":\"90V – 520V DC\"},{\"label\":\"Số lượng MPPT\",\"value\":\"2 MPPT\"},{\"label\":\"Tương thích pin lưu trữ\",\"value\":\"Pin Lithium 48V / 51.2V (LiFePO4)\"},{\"label\":\"Thời gian chuyển mạch UPS\",\"value\":\"< 10 ms (Cấp nguồn liên tục không ngắt quãng)\"},{\"label\":\"Hiệu suất tối đa\",\"value\":\"97.6\% - 98.2\%\"},{\"label\":\"Cấp độ bảo vệ môi trường\",\"value\":\"IP65 / IP66 (Lắp đặt trong nhà hoặc ngoài trời)\"},{\"label\":\"Cổng giao tiếp giám sát\",\"value\":\"RS485, CAN, Wi-Fi / LAN, DRM\"},{\"label\":\"Bảo hành tiêu chuẩn\",\"value\":\"5 năm chính hãng (Mở rộng tùy chọn đến 10 năm)\"}]'),
(65, 'san-pham-65', 2, 'Inverter hòa lưới Deye SUN-80K-G | 3 pha | 4 MPPT', '65640120', 65640120, NULL, '/uploads/products/inverter/41', 'Inverter hòa lưới Deye SUN-80K-G | 3 pha | 4 MPPT - Chính hãng Deye', 'Deye', 'published', 650, 'Inverter hòa lưới Deye SUN-80K-G | 3 pha | 4 MPPT là dòng biến tần hòa lưới (On-grid Inverter) hiệu suất cao của thương hiệu Deye, được tối ưu hóa cho hiệu năng phát điện bền bỉ và ổn định tối đa dưới điều kiện khí hậu nhiệt đới.\n\nThiết bị tích hợp công nghệ dò điểm công suất cực đại MPPT tiên tiến với dải điện áp làm việc rộng, giúp khởi động sớm và tắt muộn để tận dụng tối đa năng lượng mặt trời mỗi ngày. Hệ thống tản nhiệt thông minh không dùng quạt ngoài (đối với model dân dụng) hoặc quạt tản nhiệt thông minh IP68 giúp máy hoạt động êm ái, kéo dài tuổi thọ linh kiện.\n\nHỗ trợ kết nối giám sát từ xa thông minh qua ứng dụng di động Cloud, tích hợp sẵn các cấp độ bảo vệ an toàn: chống sét lan truyền Type II (DC/AC), chống đảo pha, bảo vệ quá áp, quá dòng và chức năng ngắt hồ quang AFCI an toàn phòng chống cháy nổ.', '[{\"label\":\"Loại biến tần\",\"value\":\"Biến tần hòa lưới 3 Pha\"},{\"label\":\"Công suất phát định mức\",\"value\":\"80 kW\"},{\"label\":\"Điện áp ra AC\",\"value\":\"3 Pha (380V / 400V, 3L+N+PE)\"},{\"label\":\"Điện áp đầu vào PV cực đại\",\"value\":\"1000V - 1100V DC\"},{\"label\":\"Dải điện áp hoạt động MPPT\",\"value\":\"160V – 960V DC\"},{\"label\":\"Số lượng bộ theo dõi MPPT\",\"value\":\"4 MPPT\"},{\"label\":\"Hiệu suất chuyển đổi cực đại\",\"value\":\"98.6\% - 98.8\%\"},{\"label\":\"Tần số điện lưới danh định\",\"value\":\"50 Hz / 60 Hz (Tự động thích ứng)\"},{\"label\":\"Cấp bảo vệ chống nước, bụi\",\"value\":\"IP65 / IP66 tiêu chuẩn quốc tế\"},{\"label\":\"Tính năng bảo vệ\",\"value\":\"Chống phát ngược (Zero-export), chống đảo pha, AFCI\"},{\"label\":\"Giao thức truyền thông\",\"value\":\"Wi-Fi, RS485, GPRS / 4G (Tùy chọn)\"},{\"label\":\"Thời gian bảo hành\",\"value\":\"5 năm tiêu chuẩn từ nhà sản xuất\"}]'),
(66, 'san-pham-66', 2, 'Inverter hòa lưới Deye SUN-6K-G | 1 pha | 2 MPPT', '11924640', 11924640, NULL, '/uploads/products/inverter/42', 'Inverter hòa lưới Deye SUN-6K-G | 1 pha | 2 MPPT - Chính hãng Deye', 'Deye', 'published', 660, 'Inverter hòa lưới Deye SUN-6K-G | 1 pha | 2 MPPT là dòng biến tần hòa lưới (On-grid Inverter) hiệu suất cao của thương hiệu Deye, được tối ưu hóa cho hiệu năng phát điện bền bỉ và ổn định tối đa dưới điều kiện khí hậu nhiệt đới.\n\nThiết bị tích hợp công nghệ dò điểm công suất cực đại MPPT tiên tiến với dải điện áp làm việc rộng, giúp khởi động sớm và tắt muộn để tận dụng tối đa năng lượng mặt trời mỗi ngày. Hệ thống tản nhiệt thông minh không dùng quạt ngoài (đối với model dân dụng) hoặc quạt tản nhiệt thông minh IP68 giúp máy hoạt động êm ái, kéo dài tuổi thọ linh kiện.\n\nHỗ trợ kết nối giám sát từ xa thông minh qua ứng dụng di động Cloud, tích hợp sẵn các cấp độ bảo vệ an toàn: chống sét lan truyền Type II (DC/AC), chống đảo pha, bảo vệ quá áp, quá dòng và chức năng ngắt hồ quang AFCI an toàn phòng chống cháy nổ.', '[{\"label\":\"Loại biến tần\",\"value\":\"Biến tần hòa lưới 1 Pha\"},{\"label\":\"Công suất phát định mức\",\"value\":\"6 kW\"},{\"label\":\"Điện áp ra AC\",\"value\":\"1 Pha (220V / 230V, L+N+PE)\"},{\"label\":\"Điện áp đầu vào PV cực đại\",\"value\":\"550V - 600V DC\"},{\"label\":\"Dải điện áp hoạt động MPPT\",\"value\":\"90V – 520V DC\"},{\"label\":\"Số lượng bộ theo dõi MPPT\",\"value\":\"2 MPPT\"},{\"label\":\"Hiệu suất chuyển đổi cực đại\",\"value\":\"97.6\% - 98.2\%\"},{\"label\":\"Tần số điện lưới danh định\",\"value\":\"50 Hz / 60 Hz (Tự động thích ứng)\"},{\"label\":\"Cấp bảo vệ chống nước, bụi\",\"value\":\"IP65 / IP66 tiêu chuẩn quốc tế\"},{\"label\":\"Tính năng bảo vệ\",\"value\":\"Chống phát ngược (Zero-export), chống đảo pha, AFCI\"},{\"label\":\"Giao thức truyền thông\",\"value\":\"Wi-Fi, RS485, GPRS / 4G (Tùy chọn)\"},{\"label\":\"Thời gian bảo hành\",\"value\":\"5 năm tiêu chuẩn từ nhà sản xuất\"}]'),
