(95, 'san-pham-95', 2, 'Inverter hòa lưới Deye SUN-3K-G04P1-EU-AM1 | 1 pha | 1 MPPT', '8353800', 8353800, NULL, '/uploads/products/inverter/71', 'Inverter hòa lưới Deye SUN-3K-G04P1-EU-AM1 | 1 pha | 1 MPPT - Chính hãng Deye', 'Deye', 'published', 950, 'Inverter hòa lưới Deye SUN-3K-G04P1-EU-AM1 | 1 pha | 1 MPPT là dòng biến tần hòa lưới (On-grid Inverter) hiệu suất cao của thương hiệu Deye, được tối ưu hóa cho hiệu năng phát điện bền bỉ và ổn định tối đa dưới điều kiện khí hậu nhiệt đới.\n\nThiết bị tích hợp công nghệ dò điểm công suất cực đại MPPT tiên tiến với dải điện áp làm việc rộng, giúp khởi động sớm và tắt muộn để tận dụng tối đa năng lượng mặt trời mỗi ngày. Hệ thống tản nhiệt thông minh không dùng quạt ngoài (đối với model dân dụng) hoặc quạt tản nhiệt thông minh IP68 giúp máy hoạt động êm ái, kéo dài tuổi thọ linh kiện.\n\nHỗ trợ kết nối giám sát từ xa thông minh qua ứng dụng di động Cloud, tích hợp sẵn các cấp độ bảo vệ an toàn: chống sét lan truyền Type II (DC/AC), chống đảo pha, bảo vệ quá áp, quá dòng và chức năng ngắt hồ quang AFCI an toàn phòng chống cháy nổ.', '[{\"label\":\"Loại biến tần\",\"value\":\"Biến tần hòa lưới 3 Pha\"},{\"label\":\"Công suất phát định mức\",\"value\":\"3 kW\"},{\"label\":\"Điện áp ra AC\",\"value\":\"3 Pha (380V / 400V, 3L+N+PE)\"},{\"label\":\"Điện áp đầu vào PV cực đại\",\"value\":\"1000V - 1100V DC\"},{\"label\":\"Dải điện áp hoạt động MPPT\",\"value\":\"160V – 960V DC\"},{\"label\":\"Số lượng bộ theo dõi MPPT\",\"value\":\"1 MPPT\"},{\"label\":\"Hiệu suất chuyển đổi cực đại\",\"value\":\"98.6\% - 98.8\%\"},{\"label\":\"Tần số điện lưới danh định\",\"value\":\"50 Hz / 60 Hz (Tự động thích ứng)\"},{\"label\":\"Cấp bảo vệ chống nước, bụi\",\"value\":\"IP65 / IP66 tiêu chuẩn quốc tế\"},{\"label\":\"Tính năng bảo vệ\",\"value\":\"Chống phát ngược (Zero-export), chống đảo pha, AFCI\"},{\"label\":\"Giao thức truyền thông\",\"value\":\"Wi-Fi, RS485, GPRS / 4G (Tùy chọn)\"},{\"label\":\"Thời gian bảo hành\",\"value\":\"5 năm tiêu chuẩn từ nhà sản xuất\"}]'),
(96, 'san-pham-96', 2, 'Inverter Hybrid Deye SUN-8K-SG04LP3-EU', '54425280', 54425280, NULL, '/uploads/products/inverter/72', 'Inverter Hybrid Deye SUN-8K-SG04LP3-EU - Chính hãng Deye', 'Deye', 'published', 960, 'Inverter Hybrid Deye SUN-8K-SG04LP3-EU là thiết bị biến tần lưu trữ thông minh (Hybrid Inverter) cao cấp đến từ thương hiệu Deye, giải pháp toàn diện cho nguồn điện ổn định 24/7. Thiết bị cho phép điều phối linh hoạt giữa nguồn năng lượng mặt trời, pin lưu trữ và điện lưới quốc gia.\n\nSản phẩm sở hữu chức năng chuyển đổi nguồn dự phòng UPS siêu tốc (< 10ms), đảm bảo các tải quan trọng không bị gián đoạn khi xảy ra sự cố mất điện lưới. Tích hợp màn hình cảm ứng LCD hoặc đèn hiển thị LED trực quan, cùng cổng kết nối thông minh Wi-Fi/4G giúp theo dõi sản lượng và quản lý năng lượng theo thời gian thực trên điện thoại di động.\n\nTương thích hoàn hảo với các dòng pin lưu trữ Lithium điện áp thấp (48V/51.2V) hoặc áp cao (High Voltage), hỗ trợ cài đặt xả theo giờ cao điểm (Peak-shaving) và kiểm soát bám tải không phát ngược lưới Zero-Export an toàn, thông minh.', '[{\"label\":\"Loại biến tần\",\"value\":\"Biến tần lưu trữ Hybrid 3 Pha\"},{\"label\":\"Công suất AC định mức\",\"value\":\"8 kW\"},{\"label\":\"Điện áp đầu ra lưới\",\"value\":\"3 Pha (380V / 400V, 3L+N+PE)\"},{\"label\":\"Điện áp đầu vào PV cực đại\",\"value\":\"1000V - 1100V DC\"},{\"label\":\"Dải điện áp MPPT\",\"value\":\"160V – 960V DC\"},{\"label\":\"Số lượng MPPT\",\"value\":\"2 MPPT\"},{\"label\":\"Tương thích pin lưu trữ\",\"value\":\"Pin Lithium 48V / 51.2V (LiFePO4)\"},{\"label\":\"Thời gian chuyển mạch UPS\",\"value\":\"< 10 ms (Cấp nguồn liên tục không ngắt quãng)\"},{\"label\":\"Hiệu suất tối đa\",\"value\":\"98.6\% - 98.8\%\"},{\"label\":\"Cấp độ bảo vệ môi trường\",\"value\":\"IP65 / IP66 (Lắp đặt trong nhà hoặc ngoài trời)\"},{\"label\":\"Cổng giao tiếp giám sát\",\"value\":\"RS485, CAN, Wi-Fi / LAN, DRM\"},{\"label\":\"Bảo hành tiêu chuẩn\",\"value\":\"5 năm chính hãng (Mở rộng tùy chọn đến 10 năm)\"}]'),
(97, 'san-pham-97', 3, 'Pin lưu trữ Solis IntelliHome 16kWh - OD', '61066000', 61066000, NULL, '/uploads/products/pin_luu_tru/1', 'Pin lưu trữ Solis IntelliHome 16kWh - OD - Chính hãng Solis', 'Solis', 'published', 970, 'Pin lưu trữ Solis IntelliHome 16kWh - OD sử dụng công nghệ tế bào pin LiFePO4 (Lithium Iron Phosphate) tiên tiến nhất hiện nay, cung cấp giải pháp lưu trữ năng lượng an toàn, tin cậy tuyệt đối và có tuổi thọ vượt trội so với các loại ắc quy axit-chì truyền thống.\n\nSản phẩm được tích hợp mạch quản lý pin thông minh (BMS - Battery Management System) chuyên sâu, liên tục giám sát và tự động cân bằng điện áp từng cell, bảo vệ chống quá nạp, quá xả, quá dòng và kiểm soát nhiệt độ nhiều tầng. Khả năng kết nối song song nhiều bộ pin giúp dễ dàng mở rộng dung lượng khi nhu cầu tiêu thụ điện gia tăng.\n\nTương thích liền mạch thông qua giao thức CAN/RS485 với hầu hết các thương hiệu Inverter Hybrid hàng đầu trên thị trường (Deye, Solis, Luxpower, Growatt, GoodWe, SMA...). Sản phẩm đảm bảo cung cấp nguồn điện liên tục, ổn định cho gia đình và doanh nghiệp.', '[{\"label\":\"Công nghệ tế bào pin\",\"value\":\"Lithium Iron Phosphate (LiFePO4) an toàn cao\"},{\"label\":\"Dung lượng lưu trữ định mức\",\"value\":\"16 kWh (314 Ah)\"},{\"label\":\"Điện áp danh định\",\"value\":\"51.2 V\"},{\"label\":\"Dải điện áp hoạt động\",\"value\":\"44.8V – 57.6V DC\"},{\"label\":\"Độ sâu xả (DoD)\",\"value\":\"Khuyên dùng 90\% (Hỗ trợ xả sâu đến 95\%)\"},{\"label\":\"Vòng đời chu kỳ (Cycle Life)\",\"value\":\"≥ 6.000 chu kỳ @ 80\% DOD (25°C)\"},{\"label\":\"Kiểu dáng lắp đặt\",\"value\":\"Dạng tủ đứng đặt sàn / modul công suất lớn\"},{\"label\":\"Khả năng mở rộng\",\"value\":\"Hỗ trợ ghép nối song song tối đa 15 - 32 bộ\"},{\"label\":\"Cổng giao tiếp truyền thông\",\"value\":\"CAN 2.0 / RS485 / RS232 với BMS thông minh\"},{\"label\":\"Tiêu chuẩn bảo vệ & Trọng lượng\",\"value\":\"IP20 / IP55 / IP65 | Khối lượng: ~115 - 130 kg\"},{\"label\":\"Chứng nhận chất lượng\",\"value\":\"UN38.3, IEC62619, CE, MSDS quốc tế\"},{\"label\":\"Chế độ bảo hành\",\"value\":\"5 - 10 năm chính hãng\"}]'),
(98, 'san-pham-98', 3, 'Pin lưu trữ LVTOPSUN G3 16.07kWh (51.2v 314Ah)', '46575000', 46575000, NULL, '/uploads/products/pin_luu_tru/2', 'Pin lưu trữ LVTOPSUN G3 16.07kWh (51.2v 314Ah) - Chính hãng LVTOPSUN', 'LVTOPSUN', 'published', 980, 'Pin lưu trữ LVTOPSUN G3 16.07kWh (51.2v 314Ah) sử dụng công nghệ tế bào pin LiFePO4 (Lithium Iron Phosphate) tiên tiến nhất hiện nay, cung cấp giải pháp lưu trữ năng lượng an toàn, tin cậy tuyệt đối và có tuổi thọ vượt trội so với các loại ắc quy axit-chì truyền thống.\n\nSản phẩm được tích hợp mạch quản lý pin thông minh (BMS - Battery Management System) chuyên sâu, liên tục giám sát và tự động cân bằng điện áp từng cell, bảo vệ chống quá nạp, quá xả, quá dòng và kiểm soát nhiệt độ nhiều tầng. Khả năng kết nối song song nhiều bộ pin giúp dễ dàng mở rộng dung lượng khi nhu cầu tiêu thụ điện gia tăng.\n\nTương thích liền mạch thông qua giao thức CAN/RS485 với hầu hết các thương hiệu Inverter Hybrid hàng đầu trên thị trường (Deye, Solis, Luxpower, Growatt, GoodWe, SMA...). Sản phẩm đảm bảo cung cấp nguồn điện liên tục, ổn định cho gia đình và doanh nghiệp.', '[{\"label\":\"Công nghệ tế bào pin\",\"value\":\"Lithium Iron Phosphate (LiFePO4) an toàn cao\"},{\"label\":\"Dung lượng lưu trữ định mức\",\"value\":\"16.07 kWh (314 Ah)\"},{\"label\":\"Điện áp danh định\",\"value\":\"51.2 V\"},{\"label\":\"Dải điện áp hoạt động\",\"value\":\"44.8V – 57.6V DC\"},{\"label\":\"Độ sâu xả (DoD)\",\"value\":\"Khuyên dùng 90\% (Hỗ trợ xả sâu đến 95\%)\"},{\"label\":\"Vòng đời chu kỳ (Cycle Life)\",\"value\":\"≥ 6.000 chu kỳ @ 80\% DOD (25°C)\"},{\"label\":\"Kiểu dáng lắp đặt\",\"value\":\"Dạng tủ đứng đặt sàn / modul công suất lớn\"},{\"label\":\"Khả năng mở rộng\",\"value\":\"Hỗ trợ ghép nối song song tối đa 15 - 32 bộ\"},{\"label\":\"Cổng giao tiếp truyền thông\",\"value\":\"CAN 2.0 / RS485 / RS232 với BMS thông minh\"},{\"label\":\"Tiêu chuẩn bảo vệ & Trọng lượng\",\"value\":\"IP20 / IP55 / IP65 | Khối lượng: ~115 - 130 kg\"},{\"label\":\"Chứng nhận chất lượng\",\"value\":\"UN38.3, IEC62619, CE, MSDS quốc tế\"},{\"label\":\"Chế độ bảo hành\",\"value\":\"5 - 10 năm chính hãng\"}]'),
(99, 'san-pham-99', 3, 'Pin lưu trữ LVTOPSUN 512314 G4 16.07kWh', '50025000', 50025000, NULL, '/uploads/products/pin_luu_tru/3', 'Pin lưu trữ LVTOPSUN 512314 G4 16.07kWh - Chính hãng LVTOPSUN', 'LVTOPSUN', 'published', 990, 'Pin lưu trữ LVTOPSUN 512314 G4 16.07kWh sử dụng công nghệ tế bào pin LiFePO4 (Lithium Iron Phosphate) tiên tiến nhất hiện nay, cung cấp giải pháp lưu trữ năng lượng an toàn, tin cậy tuyệt đối và có tuổi thọ vượt trội so với các loại ắc quy axit-chì truyền thống.\n\nSản phẩm được tích hợp mạch quản lý pin thông minh (BMS - Battery Management System) chuyên sâu, liên tục giám sát và tự động cân bằng điện áp từng cell, bảo vệ chống quá nạp, quá xả, quá dòng và kiểm soát nhiệt độ nhiều tầng. Khả năng kết nối song song nhiều bộ pin giúp dễ dàng mở rộng dung lượng khi nhu cầu tiêu thụ điện gia tăng.\n\nTương thích liền mạch thông qua giao thức CAN/RS485 với hầu hết các thương hiệu Inverter Hybrid hàng đầu trên thị trường (Deye, Solis, Luxpower, Growatt, GoodWe, SMA...). Sản phẩm đảm bảo cung cấp nguồn điện liên tục, ổn định cho gia đình và doanh nghiệp.', '[{\"label\":\"Công nghệ tế bào pin\",\"value\":\"Lithium Iron Phosphate (LiFePO4) an toàn cao\"},{\"label\":\"Dung lượng lưu trữ định mức\",\"value\":\"16.07 kWh (314 Ah)\"},{\"label\":\"Điện áp danh định\",\"value\":\"51.2 V\"},{\"label\":\"Dải điện áp hoạt động\",\"value\":\"44.8V – 57.6V DC\"},{\"label\":\"Độ sâu xả (DoD)\",\"value\":\"Khuyên dùng 90\% (Hỗ trợ xả sâu đến 95\%)\"},{\"label\":\"Vòng đời chu kỳ (Cycle Life)\",\"value\":\"≥ 6.000 chu kỳ @ 80\% DOD (25°C)\"},{\"label\":\"Kiểu dáng lắp đặt\",\"value\":\"Dạng tủ đứng đặt sàn / modul công suất lớn\"},{\"label\":\"Khả năng mở rộng\",\"value\":\"Hỗ trợ ghép nối song song tối đa 15 - 32 bộ\"},{\"label\":\"Cổng giao tiếp truyền thông\",\"value\":\"CAN 2.0 / RS485 / RS232 với BMS thông minh\"},{\"label\":\"Tiêu chuẩn bảo vệ & Trọng lượng\",\"value\":\"IP20 / IP55 / IP65 | Khối lượng: ~115 - 130 kg\"},{\"label\":\"Chứng nhận chất lượng\",\"value\":\"UN38.3, IEC62619, CE, MSDS quốc tế\"},{\"label\":\"Chế độ bảo hành\",\"value\":\"5 - 10 năm chính hãng\"}]'),
(100, 'san-pham-100', 3, 'Pin lưu trữ Dyness BX51100 5.12 kWh', '21198000', 21198000, NULL, '/uploads/products/pin_luu_tru/4', 'Pin lưu trữ Dyness BX51100 5.12 kWh - Chính hãng Dyness', 'Dyness', 'published', 1000, 'Pin lưu trữ Dyness BX51100 5.12 kWh sử dụng công nghệ tế bào pin LiFePO4 (Lithium Iron Phosphate) tiên tiến nhất hiện nay, cung cấp giải pháp lưu trữ năng lượng an toàn, tin cậy tuyệt đối và có tuổi thọ vượt trội so với các loại ắc quy axit-chì truyền thống.\n\nSản phẩm được tích hợp mạch quản lý pin thông minh (BMS - Battery Management System) chuyên sâu, liên tục giám sát và tự động cân bằng điện áp từng cell, bảo vệ chống quá nạp, quá xả, quá dòng và kiểm soát nhiệt độ nhiều tầng. Khả năng kết nối song song nhiều bộ pin giúp dễ dàng mở rộng dung lượng khi nhu cầu tiêu thụ điện gia tăng.\n\nTương thích liền mạch thông qua giao thức CAN/RS485 với hầu hết các thương hiệu Inverter Hybrid hàng đầu trên thị trường (Deye, Solis, Luxpower, Growatt, GoodWe, SMA...). Sản phẩm đảm bảo cung cấp nguồn điện liên tục, ổn định cho gia đình và doanh nghiệp.', '[{\"label\":\"Công nghệ tế bào pin\",\"value\":\"Lithium Iron Phosphate (LiFePO4) an toàn cao\"},{\"label\":\"Dung lượng lưu trữ định mức\",\"value\":\"5.12 kWh (100 Ah)\"},{\"label\":\"Điện áp danh định\",\"value\":\"51.2 V\"},{\"label\":\"Dải điện áp hoạt động\",\"value\":\"44.8V – 57.6V DC\"},{\"label\":\"Độ sâu xả (DoD)\",\"value\":\"Khuyên dùng 90\% (Hỗ trợ xả sâu đến 95\%)\"},{\"label\":\"Vòng đời chu kỳ (Cycle Life)\",\"value\":\"≥ 6.000 chu kỳ @ 80\% DOD (25°C)\"},{\"label\":\"Kiểu dáng lắp đặt\",\"value\":\"Treo tường hoặc gắn tủ rack\"},{\"label\":\"Khả năng mở rộng\",\"value\":\"Hỗ trợ ghép nối song song tối đa 15 - 32 bộ\"},{\"label\":\"Cổng giao tiếp truyền thông\",\"value\":\"CAN 2.0 / RS485 / RS232 với BMS thông minh\"},{\"label\":\"Tiêu chuẩn bảo vệ & Trọng lượng\",\"value\":\"IP20 / IP55 / IP65 | Khối lượng: ~45 kg\"},{\"label\":\"Chứng nhận chất lượng\",\"value\":\"UN38.3, IEC62619, CE, MSDS quốc tế\"},{\"label\":\"Chế độ bảo hành\",\"value\":\"5 - 10 năm chính hãng\"}]'),
