(111, 'san-pham-111', 3, 'Pin lưu trữ Dyness STACK100 Áp Cao', '98625000', 98625000, NULL, '/uploads/products/pin_luu_tru/15', 'Pin lưu trữ Dyness STACK100 Áp Cao - Chính hãng Dyness', 'Dyness', 'published', 1110, 'Pin lưu trữ Dyness STACK100 Áp Cao sử dụng công nghệ tế bào pin LiFePO4 (Lithium Iron Phosphate) tiên tiến nhất hiện nay, cung cấp giải pháp lưu trữ năng lượng an toàn, tin cậy tuyệt đối và có tuổi thọ vượt trội so với các loại ắc quy axit-chì truyền thống.\n\nSản phẩm được tích hợp mạch quản lý pin thông minh (BMS - Battery Management System) chuyên sâu, liên tục giám sát và tự động cân bằng điện áp từng cell, bảo vệ chống quá nạp, quá xả, quá dòng và kiểm soát nhiệt độ nhiều tầng. Khả năng kết nối song song nhiều bộ pin giúp dễ dàng mở rộng dung lượng khi nhu cầu tiêu thụ điện gia tăng.\n\nTương thích liền mạch thông qua giao thức CAN/RS485 với hầu hết các thương hiệu Inverter Hybrid hàng đầu trên thị trường (Deye, Solis, Luxpower, Growatt, GoodWe, SMA...). Sản phẩm đảm bảo cung cấp nguồn điện liên tục, ổn định cho gia đình và doanh nghiệp.', '[{\"label\":\"Công nghệ tế bào pin\",\"value\":\"Lithium Iron Phosphate (LiFePO4) an toàn cao\"},{\"label\":\"Dung lượng lưu trữ định mức\",\"value\":\"43 kWh - 215 kWh (100 Ah)\"},{\"label\":\"Điện áp danh định\",\"value\":\"Áp cao HV (192V - 600V tùy số module)\"},{\"label\":\"Dải điện áp hoạt động\",\"value\":\"150V – 600V DC\"},{\"label\":\"Độ sâu xả (DoD)\",\"value\":\"Khuyên dùng 90\% (Hỗ trợ xả sâu đến 95\%)\"},{\"label\":\"Vòng đời chu kỳ (Cycle Life)\",\"value\":\"≥ 6.000 chu kỳ @ 80\% DOD (25°C)\"},{\"label\":\"Kiểu dáng lắp đặt\",\"value\":\"Hệ module xếp chồng cao cấp (Stackable Tower)\"},{\"label\":\"Khả năng mở rộng\",\"value\":\"Hỗ trợ ghép nối song song tối đa 15 - 32 bộ\"},{\"label\":\"Cổng giao tiếp truyền thông\",\"value\":\"CAN 2.0 / RS485 / RS232 với BMS thông minh\"},{\"label\":\"Tiêu chuẩn bảo vệ & Trọng lượng\",\"value\":\"IP20 / IP55 / IP65 | Khối lượng: ~Tùy biến công nghiệp\"},{\"label\":\"Chứng nhận chất lượng\",\"value\":\"UN38.3, IEC62619, CE, MSDS quốc tế\"},{\"label\":\"Chế độ bảo hành\",\"value\":\"5 - 10 năm chính hãng\"}]'),
(112, 'san-pham-112', 3, 'Pin lưu trữ áp cao LVTOPSUN LVTS-5220-HV', '122522400', 122522400, NULL, '/uploads/products/pin_luu_tru/16', 'Pin lưu trữ áp cao LVTOPSUN LVTS-5220-HV - Chính hãng LVTOPSUN', 'LVTOPSUN', 'published', 1120, 'Pin lưu trữ áp cao LVTOPSUN LVTS-5220-HV sử dụng công nghệ tế bào pin LiFePO4 (Lithium Iron Phosphate) tiên tiến nhất hiện nay, cung cấp giải pháp lưu trữ năng lượng an toàn, tin cậy tuyệt đối và có tuổi thọ vượt trội so với các loại ắc quy axit-chì truyền thống.\n\nSản phẩm được tích hợp mạch quản lý pin thông minh (BMS - Battery Management System) chuyên sâu, liên tục giám sát và tự động cân bằng điện áp từng cell, bảo vệ chống quá nạp, quá xả, quá dòng và kiểm soát nhiệt độ nhiều tầng. Khả năng kết nối song song nhiều bộ pin giúp dễ dàng mở rộng dung lượng khi nhu cầu tiêu thụ điện gia tăng.\n\nTương thích liền mạch thông qua giao thức CAN/RS485 với hầu hết các thương hiệu Inverter Hybrid hàng đầu trên thị trường (Deye, Solis, Luxpower, Growatt, GoodWe, SMA...). Sản phẩm đảm bảo cung cấp nguồn điện liên tục, ổn định cho gia đình và doanh nghiệp.', '[{\"label\":\"Công nghệ tế bào pin\",\"value\":\"Lithium Iron Phosphate (LiFePO4) an toàn cao\"},{\"label\":\"Dung lượng lưu trữ định mức\",\"value\":\"43 kWh - 215 kWh (100 Ah)\"},{\"label\":\"Điện áp danh định\",\"value\":\"Áp cao HV (192V - 600V tùy số module)\"},{\"label\":\"Dải điện áp hoạt động\",\"value\":\"150V – 600V DC\"},{\"label\":\"Độ sâu xả (DoD)\",\"value\":\"Khuyên dùng 90\% (Hỗ trợ xả sâu đến 95\%)\"},{\"label\":\"Vòng đời chu kỳ (Cycle Life)\",\"value\":\"≥ 6.000 chu kỳ @ 80\% DOD (25°C)\"},{\"label\":\"Kiểu dáng lắp đặt\",\"value\":\"Hệ module xếp chồng cao cấp (Stackable Tower)\"},{\"label\":\"Khả năng mở rộng\",\"value\":\"Hỗ trợ ghép nối song song tối đa 15 - 32 bộ\"},{\"label\":\"Cổng giao tiếp truyền thông\",\"value\":\"CAN 2.0 / RS485 / RS232 với BMS thông minh\"},{\"label\":\"Tiêu chuẩn bảo vệ & Trọng lượng\",\"value\":\"IP20 / IP55 / IP65 | Khối lượng: ~Tùy biến công nghiệp\"},{\"label\":\"Chứng nhận chất lượng\",\"value\":\"UN38.3, IEC62619, CE, MSDS quốc tế\"},{\"label\":\"Chế độ bảo hành\",\"value\":\"5 - 10 năm chính hãng\"}]'),
