(129, 'san-pham-129', 3, 'Pin lưu trữ Lithium SVE Plus 14.3kW', '49350000', 49350000, NULL, '/uploads/products/pin_luu_tru/33', 'Pin lưu trữ Lithium SVE Plus 14.3kW - Chính hãng SVE', 'SVE', 'published', 1290, 'Pin lưu trữ Lithium SVE Plus 14.3kW sử dụng công nghệ tế bào pin LiFePO4 (Lithium Iron Phosphate) tiên tiến nhất hiện nay, cung cấp giải pháp lưu trữ năng lượng an toàn, tin cậy tuyệt đối và có tuổi thọ vượt trội so với các loại ắc quy axit-chì truyền thống.\n\nSản phẩm được tích hợp mạch quản lý pin thông minh (BMS - Battery Management System) chuyên sâu, liên tục giám sát và tự động cân bằng điện áp từng cell, bảo vệ chống quá nạp, quá xả, quá dòng và kiểm soát nhiệt độ nhiều tầng. Khả năng kết nối song song nhiều bộ pin giúp dễ dàng mở rộng dung lượng khi nhu cầu tiêu thụ điện gia tăng.\n\nTương thích liền mạch thông qua giao thức CAN/RS485 với hầu hết các thương hiệu Inverter Hybrid hàng đầu trên thị trường (Deye, Solis, Luxpower, Growatt, GoodWe, SMA...). Sản phẩm đảm bảo cung cấp nguồn điện liên tục, ổn định cho gia đình và doanh nghiệp.', '[{\"label\":\"Công nghệ tế bào pin\",\"value\":\"Lithium Iron Phosphate (LiFePO4) an toàn cao\"},{\"label\":\"Dung lượng lưu trữ định mức\",\"value\":\"14.3 kWh (280 Ah)\"},{\"label\":\"Điện áp danh định\",\"value\":\"51.2 V\"},{\"label\":\"Dải điện áp hoạt động\",\"value\":\"44.8V – 57.6V DC\"},{\"label\":\"Độ sâu xả (DoD)\",\"value\":\"Khuyên dùng 90\% (Hỗ trợ xả sâu đến 95\%)\"},{\"label\":\"Vòng đời chu kỳ (Cycle Life)\",\"value\":\"≥ 6.000 chu kỳ @ 80\% DOD (25°C)\"},{\"label\":\"Kiểu dáng lắp đặt\",\"value\":\"Dạng tủ đứng đặt sàn / treo tường công suất lớn\"},{\"label\":\"Khả năng mở rộng\",\"value\":\"Hỗ trợ ghép nối song song tối đa 15 - 32 bộ\"},{\"label\":\"Cổng giao tiếp truyền thông\",\"value\":\"CAN 2.0 / RS485 / RS232 với BMS thông minh\"},{\"label\":\"Tiêu chuẩn bảo vệ & Trọng lượng\",\"value\":\"IP20 / IP55 / IP65 | Khối lượng: ~108 kg\"},{\"label\":\"Chứng nhận chất lượng\",\"value\":\"UN38.3, IEC62619, CE, MSDS quốc tế\"},{\"label\":\"Chế độ bảo hành\",\"value\":\"5 - 10 năm chính hãng\"}]'),
(130, 'san-pham-130', 3, 'Pin lưu trữ Lithium Gigabox 16s 15,62kwh', '51450000', 51450000, NULL, '/uploads/products/pin_luu_tru/34', 'Pin lưu trữ Lithium Gigabox 16s 15,62kwh - Chính hãng Gigabox', 'Gigabox', 'published', 1300, 'Pin lưu trữ Lithium Gigabox 16s 15,62kwh sử dụng công nghệ tế bào pin LiFePO4 (Lithium Iron Phosphate) tiên tiến nhất hiện nay, cung cấp giải pháp lưu trữ năng lượng an toàn, tin cậy tuyệt đối và có tuổi thọ vượt trội so với các loại ắc quy axit-chì truyền thống.\n\nSản phẩm được tích hợp mạch quản lý pin thông minh (BMS - Battery Management System) chuyên sâu, liên tục giám sát và tự động cân bằng điện áp từng cell, bảo vệ chống quá nạp, quá xả, quá dòng và kiểm soát nhiệt độ nhiều tầng. Khả năng kết nối song song nhiều bộ pin giúp dễ dàng mở rộng dung lượng khi nhu cầu tiêu thụ điện gia tăng.\n\nTương thích liền mạch thông qua giao thức CAN/RS485 với hầu hết các thương hiệu Inverter Hybrid hàng đầu trên thị trường (Deye, Solis, Luxpower, Growatt, GoodWe, SMA...). Sản phẩm đảm bảo cung cấp nguồn điện liên tục, ổn định cho gia đình và doanh nghiệp.', '[{\"label\":\"Công nghệ tế bào pin\",\"value\":\"Lithium Iron Phosphate (LiFePO4) an toàn cao\"},{\"label\":\"Dung lượng lưu trữ định mức\",\"value\":\"5.12 kWh (100 Ah)\"},{\"label\":\"Điện áp danh định\",\"value\":\"51.2 V\"},{\"label\":\"Dải điện áp hoạt động\",\"value\":\"44.8V – 57.6V DC\"},{\"label\":\"Độ sâu xả (DoD)\",\"value\":\"Khuyên dùng 90\% (Hỗ trợ xả sâu đến 95\%)\"},{\"label\":\"Vòng đời chu kỳ (Cycle Life)\",\"value\":\"≥ 6.000 chu kỳ @ 80\% DOD (25°C)\"},{\"label\":\"Kiểu dáng lắp đặt\",\"value\":\"Treo tường hoặc gắn tủ rack\"},{\"label\":\"Khả năng mở rộng\",\"value\":\"Hỗ trợ ghép nối song song tối đa 15 - 32 bộ\"},{\"label\":\"Cổng giao tiếp truyền thông\",\"value\":\"CAN 2.0 / RS485 / RS232 với BMS thông minh\"},{\"label\":\"Tiêu chuẩn bảo vệ & Trọng lượng\",\"value\":\"IP20 / IP55 / IP65 | Khối lượng: ~45 kg\"},{\"label\":\"Chứng nhận chất lượng\",\"value\":\"UN38.3, IEC62619, CE, MSDS quốc tế\"},{\"label\":\"Chế độ bảo hành\",\"value\":\"5 - 10 năm chính hãng\"}]'),
(131, 'san-pham-131', 4, 'Tủ Điện Tích Hợp Biến Tần Bơm Bedford 11kW | 3 Pha | 380V', '12020000', 12020000, NULL, '/uploads/products/phu_kien/1', 'Tủ Điện Tích Hợp Biến Tần Bơm Bedford 11kW | 3 Pha | 380V - Chính hãng Bedford', 'Bedford', 'published', 1310, 'Tủ Điện Tích Hợp Biến Tần Bơm Bedford 11kW | 3 Pha | 380V là giải pháp trọn bộ chuyên dụng cho hệ thống máy bơm nước năng lượng mặt trời, phục vụ tưới tiêu nông nghiệp, trang trại và cấp nước sinh hoạt không phụ thuộc vào điện lưới quốc gia.\n\nTủ điện được gia công chuẩn công nghiệp, sơn tĩnh điện chống ăn mòn ngoài trời, tích hợp đầy đủ các thiết bị đóng cắt bảo vệ như Aptomat DC/AC, chống sét lan truyền SPD, role nhiệt và bộ điều khiển thông minh tự động bơm khi có nắng, tự ngắt khi cạn nước hoặc bể đầy.\n\nSản phẩm vận hành bền bỉ, tiết kiệm tối đa chi phí vận hành xăng dầu và tiền điện, là giải pháp kinh tế bền vững cho bà con nông dân và các dự án thủy lợi.', '[{\"label\":\"Dòng sản phẩm\",\"value\":\"Tủ điện điều khiển biến tần bơm năng lượng mặt trời\"},{\"label\":\"Công suất động cơ tương thích\",\"value\":\"11 kW\"},{\"label\":\"Điện áp đầu ra\",\"value\":\"3 Pha 380V AC\"},{\"label\":\"Nguồn cấp hỗ trợ\",\"value\":\"Pin mặt trời DC hoặc Điện lưới AC dự phòng (Hybrid)\"},{\"label\":\"Cấp độ bảo vệ vỏ tủ\",\"value\":\"IP54 / IP65 ngoài trời chịu mưa nắng\"},{\"label\":\"Thiết bị bảo vệ tích hợp\",\"value\":\"Aptomat DC/AC, SPD chống sét, relay bảo vệ quá dòng\"},{\"label\":\"Tính năng thông minh\",\"value\":\"Tự động khởi động khi có nắng, tự ngắt khi cạn nước\"},{\"label\":\"Bảo hành\",\"value\":\"12 - 24 tháng chính hãng\"}]'),
