(135, 'san-pham-135', 4, 'Tủ Điện Tích Hợp Biến Tần Bơm Bedford 15kW | 3 Pha | 380V', '12900000', 12900000, NULL, '/uploads/products/phu_kien/5', 'Tủ Điện Tích Hợp Biến Tần Bơm Bedford 15kW | 3 Pha | 380V - Chính hãng Bedford', 'Bedford', 'published', 1350, 'Tủ Điện Tích Hợp Biến Tần Bơm Bedford 15kW | 3 Pha | 380V là giải pháp trọn bộ chuyên dụng cho hệ thống máy bơm nước năng lượng mặt trời, phục vụ tưới tiêu nông nghiệp, trang trại và cấp nước sinh hoạt không phụ thuộc vào điện lưới quốc gia.\n\nTủ điện được gia công chuẩn công nghiệp, sơn tĩnh điện chống ăn mòn ngoài trời, tích hợp đầy đủ các thiết bị đóng cắt bảo vệ như Aptomat DC/AC, chống sét lan truyền SPD, role nhiệt và bộ điều khiển thông minh tự động bơm khi có nắng, tự ngắt khi cạn nước hoặc bể đầy.\n\nSản phẩm vận hành bền bỉ, tiết kiệm tối đa chi phí vận hành xăng dầu và tiền điện, là giải pháp kinh tế bền vững cho bà con nông dân và các dự án thủy lợi.', '[{\"label\":\"Dòng sản phẩm\",\"value\":\"Tủ điện điều khiển biến tần bơm năng lượng mặt trời\"},{\"label\":\"Công suất động cơ tương thích\",\"value\":\"15 kW\"},{\"label\":\"Điện áp đầu ra\",\"value\":\"3 Pha 380V AC\"},{\"label\":\"Nguồn cấp hỗ trợ\",\"value\":\"Pin mặt trời DC hoặc Điện lưới AC dự phòng (Hybrid)\"},{\"label\":\"Cấp độ bảo vệ vỏ tủ\",\"value\":\"IP54 / IP65 ngoài trời chịu mưa nắng\"},{\"label\":\"Thiết bị bảo vệ tích hợp\",\"value\":\"Aptomat DC/AC, SPD chống sét, relay bảo vệ quá dòng\"},{\"label\":\"Tính năng thông minh\",\"value\":\"Tự động khởi động khi có nắng, tự ngắt khi cạn nước\"},{\"label\":\"Bảo hành\",\"value\":\"12 - 24 tháng chính hãng\"}]'),
