(143, 'san-pham-143', 4, 'Smart Meter Growatt SDM230-MODBUS 1 pha', '1680000', 1680000, NULL, '/uploads/products/phu_kien/13', 'Smart Meter Growatt SDM230-MODBUS 1 pha - Chính hãng Growatt', 'Growatt', 'published', 1430, 'Smart Meter Growatt SDM230-MODBUS 1 pha là thiết bị đo đếm điện năng thông minh chuyên dụng, dùng để giám sát dòng điện hai chiều trong hệ thống điện mặt trời hòa lưới và hybrid.\n\nThiết bị kết nối trực tiếp với biến tần qua cổng truyền thông RS485 Modbus để truyền dữ liệu công suất phụ tải tiêu thụ, từ đó biến tần tự động điều chỉnh công suất phát để thực hiện chức năng bám tải Zero-Export (không phát ngược lên điện lưới).\n\nĐộ chính xác đo lường Class 1 theo tiêu chuẩn quốc tế, hiển thị chi tiết các thông số điện áp, dòng điện, hệ số công suất cosφ và điện năng tiêu thụ trên màn hình LCD.', '[{\"label\":\"Loại thiết bị\",\"value\":\"Smart Meter cảm biến dòng bám tải 1 Pha\"},{\"label\":\"Thương hiệu tương thích\",\"value\":\"Growatt\"},{\"label\":\"Điện áp danh định\",\"value\":\"230V AC\"},{\"label\":\"Phương thức đo lường\",\"value\":\"Đo trực tiếp Modbus\"},{\"label\":\"Giao thức truyền thông\",\"value\":\"RS485 Modbus-RTU tốc độ 9600 bps\"},{\"label\":\"Độ chính xác đo lường\",\"value\":\"Class 1.0 (Sai số < 1\%)\"},{\"label\":\"Kiểu lắp đặt\",\"value\":\"Gắn thanh DIN-rail 35mm trong tủ điện\"},{\"label\":\"Bảo hành\",\"value\":\"24 tháng chính hãng\"}]'),
(144, 'san-pham-144', 4, 'Kẹp biên', '15000', 15000, NULL, '/uploads/products/phu_kien/14', 'Kẹp biên - Chính hãng Dang cap nhat', 'Dang cap nhat', 'published', 1440, 'Kẹp biên là phụ kiện cơ khí / phụ trợ chuyên dụng trong thi công lắp đặt hệ thống điện mặt trời, đáp ứng các tiêu chuẩn kỹ thuật khắt khe về độ bền kéo, khả năng chống ăn mòn và tuổi thọ ngoài trời.\n\nSản phẩm được gia công chính xác trên dây chuyền công nghệ cao, giúp việc thi công nhanh gọn, chắc chắn và đảm bảo an toàn tuyệt đối cho công trình trước gió bão suốt hơn 25 năm sử dụng.', '[{\"label\":\"Tên phụ kiện\",\"value\":\"Kẹp biên\"},{\"label\":\"Vật liệu chế tạo\",\"value\":\"Hợp kim nhôm cao cấp AL6005-T5 bề mặt Anodized\"},{\"label\":\"Khả năng chống chịu thời tiết\",\"value\":\"Chống ăn mòn muối biển, chống tia cực tím UV\"},{\"label\":\"Ứng dụng thi công\",\"value\":\"Hệ thống điện mặt trời áp mái tôn, mái ngói hoặc khung giàn\"},{\"label\":\"Tiêu chuẩn chất lượng\",\"value\":\"ISO 9001, AS/NZS 1170.2, SGS testing\"},{\"label\":\"Tuổi thọ thiết kế\",\"value\":\"Trên 25 năm vận hành ngoài trời\"},{\"label\":\"Bảo hành sản phẩm\",\"value\":\"10 năm chất lượng vật lý\"}]'),
