(151, 'san-pham-151', 4, 'Chổi vệ sinh tấm pin năng lượng mặt trời C21', 'Lien he', NULL, 'Liên hệ', '/uploads/products/phu_kien/21', 'Chổi vệ sinh tấm pin năng lượng mặt trời C21 - Chính hãng Dang cap nhat', 'Dang cap nhat', 'published', 1510, 'Chổi vệ sinh tấm pin năng lượng mặt trời C21 là phụ kiện cơ khí / phụ trợ chuyên dụng trong thi công lắp đặt hệ thống điện mặt trời, đáp ứng các tiêu chuẩn kỹ thuật khắt khe về độ bền kéo, khả năng chống ăn mòn và tuổi thọ ngoài trời.\n\nSản phẩm được gia công chính xác trên dây chuyền công nghệ cao, giúp việc thi công nhanh gọn, chắc chắn và đảm bảo an toàn tuyệt đối cho công trình trước gió bão suốt hơn 25 năm sử dụng.', '[{\"label\":\"Tên phụ kiện\",\"value\":\"Chổi vệ sinh tấm pin năng lượng mặt trời C21\"},{\"label\":\"Vật liệu chế tạo\",\"value\":\"Cán nhôm ống lồng carbon cao cấp, sợi cọ nilon chuyên dụng không xước kính\"},{\"label\":\"Khả năng chống chịu thời tiết\",\"value\":\"Chống ăn mòn muối biển, chống tia cực tím UV\"},{\"label\":\"Ứng dụng thi công\",\"value\":\"Vệ sinh làm sạch bề mặt tấm pin mặt trời định kỳ\"},{\"label\":\"Tiêu chuẩn chất lượng\",\"value\":\"ISO 9001, AS/NZS 1170.2, SGS testing\"},{\"label\":\"Tuổi thọ thiết kế\",\"value\":\"Trên 25 năm vận hành ngoài trời\"},{\"label\":\"Bảo hành sản phẩm\",\"value\":\"10 năm chất lượng vật lý\"}]'),
(152, 'san-pham-152', 4, 'Tủ điện tích hợp TD.PUMP.5R5P-4 | 5.5kW | 3P | 380V', '10143000', 10143000, NULL, '/uploads/products/phu_kien/22', 'Tủ điện tích hợp TD.PUMP.5R5P-4 | 5.5kW | 3P | 380V - Chính hãng INVT', 'INVT', 'published', 1520, 'Tủ điện tích hợp TD.PUMP.5R5P-4 | 5.5kW | 3P | 380V là giải pháp trọn bộ chuyên dụng cho hệ thống máy bơm nước năng lượng mặt trời, phục vụ tưới tiêu nông nghiệp, trang trại và cấp nước sinh hoạt không phụ thuộc vào điện lưới quốc gia.\n\nTủ điện được gia công chuẩn công nghiệp, sơn tĩnh điện chống ăn mòn ngoài trời, tích hợp đầy đủ các thiết bị đóng cắt bảo vệ như Aptomat DC/AC, chống sét lan truyền SPD, role nhiệt và bộ điều khiển thông minh tự động bơm khi có nắng, tự ngắt khi cạn nước hoặc bể đầy.\n\nSản phẩm vận hành bền bỉ, tiết kiệm tối đa chi phí vận hành xăng dầu và tiền điện, là giải pháp kinh tế bền vững cho bà con nông dân và các dự án thủy lợi.', '[{\"label\":\"Dòng sản phẩm\",\"value\":\"Tủ điện điều khiển biến tần bơm năng lượng mặt trời\"},{\"label\":\"Công suất động cơ tương thích\",\"value\":\"5.5 kW\"},{\"label\":\"Điện áp đầu ra\",\"value\":\"3 Pha 380V AC\"},{\"label\":\"Nguồn cấp hỗ trợ\",\"value\":\"Pin mặt trời DC hoặc Điện lưới AC dự phòng (Hybrid)\"},{\"label\":\"Cấp độ bảo vệ vỏ tủ\",\"value\":\"IP54 / IP65 ngoài trời chịu mưa nắng\"},{\"label\":\"Thiết bị bảo vệ tích hợp\",\"value\":\"Aptomat DC/AC, SPD chống sét, relay bảo vệ quá dòng\"},{\"label\":\"Tính năng thông minh\",\"value\":\"Tự động khởi động khi có nắng, tự ngắt khi cạn nước\"},{\"label\":\"Bảo hành\",\"value\":\"12 - 24 tháng chính hãng\"}]'),
